<?php require_once 'functions.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$st=$_POST['order_status']??'Pending';if($id&&in_array($st,['Pending','Processing','Shipped','Delivered','Cancelled'],true)){$s=$conn->prepare('UPDATE orders SET order_status=? WHERE id=?');$s->bind_param('si',$st,$id);$s->execute();flash('success','Order status updated.');}}redirect('admin_orders.php'); ?>
